Function Minimizing\_Values;
for $i = 0$ to $k$
    $w_i = \text{arbitrary\_value}$;
endfor
$\lambda = \text{learning\_rate}$;
repeat number\_iterations times
    for $j = 1$ to $n$
        $y = \left\{ \begin{array}{c} 1 \text{ if } w_0 + \sum_{i=1}^{k} w_i x_i^j > 0 \\ -1 \text{ otherwise} \end{array} \right.$
        $w_0 = w_0 - \lambda(y - y^j)$;
        for $m = 1$ to $k$
            $w_m = w_m - \lambda(y - y^j) x_m^j$;
        endfor
    endfor
endrepeat
